-- ====================================================================
-- SkyFly Airlines - DUMMY DATA for December 2026 (1 Dec - 30 Dec 2026)
-- Database : skyfly_db   (MySQL 8+ / MariaDB 10.4+, e.g. XAMPP)
--
-- SAFE TO RUN ON YOUR EXISTING DATABASE:
--   * It does NOT drop or truncate anything and does not touch your existing rows.
--   * It can be run more than once - rows that already exist are skipped.
--   * Run it AFTER the application has started once (so the tables exist).
--
-- What it adds  : 4 airlines, 9 airports, 42 routes (new ones only),
--                 40 customers, 1294 flights, 2195 bookings,
--                 4402 passengers and 2195 payments.
-- Login         : every new customer uses the password  Customer@123
--                 (e.g. amit.desai@example.com).  Admin / demo logins are unchanged.
-- Date range    : all flights depart and all bookings/payments are dated 2026-12-01 .. 2026-12-30.
-- To remove it  : run database/remove_dummy_data_dec2026.sql
-- ====================================================================

USE `skyfly_db`;
SET NAMES utf8mb4;

-- 1. Airlines (existing codes are skipped)

-- 2. Airports (existing codes are skipped)

-- 3. Customers (existing e-mails are skipped). Password for all: Customer@123

-- --------------------------------------------------------------------
-- Staging tables (temporary: they disappear when this script finishes)
-- --------------------------------------------------------------------
DROP TEMPORARY TABLE IF EXISTS tmp_seed_routes;
DROP TEMPORARY TABLE IF EXISTS tmp_seed_flights;
DROP TEMPORARY TABLE IF EXISTS tmp_seed_bookings;
DROP TEMPORARY TABLE IF EXISTS tmp_seed_passengers;
DROP TEMPORARY TABLE IF EXISTS tmp_new_refs;

CREATE TEMPORARY TABLE tmp_seed_routes (src VARCHAR(10), dst VARCHAR(10), distance_km INT);
CREATE TEMPORARY TABLE tmp_seed_flights (flight_number VARCHAR(20), airline_code VARCHAR(10), src VARCHAR(10), dst VARCHAR(10),
    departure_time DATETIME, arrival_time DATETIME, total_seats INT, ticket_price DECIMAL(10,2), status VARCHAR(20));
CREATE TEMPORARY TABLE tmp_seed_bookings (ref VARCHAR(20), user_email VARCHAR(120), flight_number VARCHAR(20), departure_time DATETIME,
    booking_date DATETIME, updated_at DATETIME, total_amount DECIMAL(10,2), pax INT, booking_status VARCHAR(20),
    txn VARCHAR(50), method VARCHAR(30), pay_status VARCHAR(20), pay_date DATETIME);
CREATE TEMPORARY TABLE tmp_seed_passengers (ref VARCHAR(20), full_name VARCHAR(100), age INT, gender VARCHAR(10), seat_number VARCHAR(10), passport_or_id VARCHAR(50));


-- 4. Routes (both directions; existing routes are skipped)
SELECT s.id, d.id, r.distance_km, 'ACTIVE', '2026-11-20 09:00:00'
FROM tmp_seed_routes r
JOIN `airports` s ON s.airport_code = r.src
JOIN `airports` d ON d.airport_code = r.dst;

-- 5. Flights (a flight with the same number + departure time is skipped)
SELECT t.flight_number, a.id, ro.id, t.departure_time, t.arrival_time, t.total_seats, t.total_seats, t.ticket_price, t.status, '2026-11-20 09:00:00'
FROM tmp_seed_flights t
JOIN `airlines` a ON a.airline_code = t.airline_code
JOIN `airports` s ON s.airport_code = t.src
JOIN `airports` d ON d.airport_code = t.dst
JOIN `routes` ro ON ro.source_airport_id = s.id AND ro.destination_airport_id = d.id
WHERE NOT EXISTS (SELECT 1 FROM `flights` x WHERE x.flight_number = t.flight_number AND x.departure_time = t.departure_time);

-- 6. Work out which bookings are new (so re-running never duplicates anything)
CREATE TEMPORARY TABLE tmp_new_refs (ref VARCHAR(20));
SELECT b.ref
FROM tmp_seed_bookings b
JOIN `users` u ON u.email = b.user_email
JOIN `flights` f ON f.flight_number = b.flight_number AND f.departure_time = b.departure_time
WHERE NOT EXISTS (SELECT 1 FROM `bookings` x WHERE x.booking_reference = b.ref);

-- 7. Bookings
SELECT b.ref, u.id, f.id, b.booking_date, b.total_amount, b.pax, b.booking_status, b.booking_date, b.updated_at
FROM tmp_seed_bookings b
JOIN tmp_new_refs n ON n.ref = b.ref
JOIN `users` u ON u.email = b.user_email
JOIN `flights` f ON f.flight_number = b.flight_number AND f.departure_time = b.departure_time;

-- 8. Passengers
SELECT bk.id, p.full_name, p.age, p.gender, p.seat_number, p.passport_or_id
FROM tmp_seed_passengers p
JOIN tmp_new_refs n ON n.ref = p.ref
JOIN `bookings` bk ON bk.booking_reference = p.ref;

-- 9. Payments (cancelled bookings are REFUNDED)
SELECT bk.id, b.txn, b.total_amount, b.method, b.pay_status, b.pay_date
FROM tmp_seed_bookings b
JOIN tmp_new_refs n ON n.ref = b.ref
JOIN `bookings` bk ON bk.booking_reference = b.ref;

-- 10. Keep seat counts consistent: available = total - passengers on CONFIRMED bookings
--     (only for flights departing 1-30 Dec 2026)
UPDATE `flights` f
SET f.available_seats = f.total_seats - COALESCE((SELECT SUM(bk.passenger_count) FROM `bookings` bk
                                                  WHERE bk.flight_id = f.id AND bk.booking_status = 'CONFIRMED'), 0)
WHERE f.departure_time >= '2026-12-01 00:00:00' AND f.departure_time < '2026-12-31 00:00:00';

DROP TEMPORARY TABLE IF EXISTS tmp_seed_routes;
DROP TEMPORARY TABLE IF EXISTS tmp_seed_flights;
DROP TEMPORARY TABLE IF EXISTS tmp_seed_bookings;
DROP TEMPORARY TABLE IF EXISTS tmp_seed_passengers;
DROP TEMPORARY TABLE IF EXISTS tmp_new_refs;

-- Quick check
SELECT (SELECT COUNT(*) FROM flights  WHERE departure_time >= '2026-12-01' AND departure_time < '2026-12-31') AS dec_flights,
       (SELECT COUNT(*) FROM bookings WHERE booking_date   >= '2026-12-01' AND booking_date   < '2026-12-31') AS dec_bookings,
       (SELECT COUNT(*) FROM users WHERE role = 'CUSTOMER') AS customers;
